INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(42411, 'Ezekiel 29:8', 'Ezekiel', 29, 8, 'نو زه څښتن تعالی داسې وایم: ‹زه به لښکرې درولېږم چې په تا باندې حمله وکړي او هغوی به ستا خلک او حیوانات ووژني.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_8.mp3', '', 1761754199, 1761754199),
(42412, 'Ezekiel 29:9', 'Ezekiel', 29, 9, 'مصر به وران او ویجاړ شي. بیا به پوه شئ چې زه څښتن یم. په دې خاطر چې تا فرعون ویلي وو: ”د نیل سیند زما دی او ما جوړ کړی دی،“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_9.mp3', '', 1761754199, 1761754199),
(42413, 'Ezekiel 29:10', 'Ezekiel', 29, 10, 'زه ستا او ستا د سیندونو په ضد یم. زه به ټول مصر په شمال کې د مجدل د ښار نه د اسوان تر ښاره پورې په جنوب کې او د ایتوپیا تر سرحده پورې په پوره توګه وران او ویجاړ کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_10.mp3', '', 1761754199, 1761754199),
(42414, 'Ezekiel 29:11', 'Ezekiel', 29, 11, 'په هغه کې به نه انسانان او نه حیوانات تېریږي. څلوېښت کاله به هغه ځای د اوسېدلو نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_11.mp3', '', 1761754199, 1761754199),
(42415, 'Ezekiel 29:12', 'Ezekiel', 29, 12, 'زه به مصر د نړۍ په ډېر وران او ویجاړ وطن باندې بدل کړم. څلوېښت کاله به د مصر ښارونه کنډواله پراته وي او د نورو وران شویو ښارونو نه به بدتر وي. زه به مصریان د نړۍ په قومونو او هېوادنو کې خواره واره کړم.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_12.mp3', '', 1761754199, 1761754199),
(42416, 'Ezekiel 29:13', 'Ezekiel', 29, 13, 'خو څښتن تعالی داسې وایي: ‹څلوېښت کاله وروسته به مصریان د هغو قومونو نه چې هغوی په کې خواره واره شوي وو، راټول کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_13.mp3', '', 1761754199, 1761754199),
(42417, 'Ezekiel 29:14', 'Ezekiel', 29, 14, 'زه به د مصریانو حال ښه کړم او هغوی به د مصر په جنوب کې د فتروس سیمې ته چې د هغوی اصلي ځای دی، بېرته راولم. د هغوی پاچاهي به یوه کمزورې پاچاهي وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_14.mp3', '', 1761754199, 1761754199),
(42418, 'Ezekiel 29:15', 'Ezekiel', 29, 15, 'د ټولو نه ډېره کمزورې پاچاهي او هغوی به بیا هېڅکله په نورو قومونو باندې حکومت نه کوي. زه به هغوی دومره کمزوري کړم چې ونه شي کولای په نورو قومونو باندې حکومت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_15.mp3', '', 1761754199, 1761754199),
(42419, 'Ezekiel 29:16', 'Ezekiel', 29, 16, 'اسراییل به بیا هېڅکله د مرستې په خاطر په مصریانو باندې تکیه نه کوي. د مصر سرنوشت به اسراییلو ته دا ور په یادوي چې په هغوی باندې تکیه کول څومره ګناه وه. بیا به اسراییل په دې پوه شي چې زه څښتن تعالی یم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_16.mp3', '', 1761754199, 1761754199),
(42420, 'Ezekiel 29:17', 'Ezekiel', 29, 17, 'زمونږ د جلاوطنۍ په اووه ویشتم کال د لومړۍ میاشتې په لومړۍ ورځ څښتن ماته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_17.mp3', '', 1761754199, 1761754199),
(42421, 'Ezekiel 29:18', 'Ezekiel', 29, 18, '«ای فاني انسانه، د بابل پاچا د صور په ښار باندې حمله وکړه. هغه خپل عسکر مجبور کړل چې دومره درانه بارونه یوسي چې د هغوی سرونه ګنجیان شول او اوږې یې تڼاکې شولې، خو پاچا او د هغه لښکرو د هغو ټولو زحمتونو نه چې هغوی وویستل کومه ګټه تر‌لاسه نه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_18.mp3', '', 1761754199, 1761754199),
(42422, 'Ezekiel 29:19', 'Ezekiel', 29, 19, 'نو زه څښتن تعالی داسې وایم: ‹ګوره، زه به د مصر هېواد د مصر پاچا نبوکدنصر ته ورکړم. هغوی به هغه لوټ او تالا کړي او د مصر ټول مال او دولت به یوسي او خپلو عسکرو ته به یې د معاش په توګه ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_19.mp3', '', 1761754199, 1761754199),
(42423, 'Ezekiel 29:20', 'Ezekiel', 29, 20, 'زه به هغه ته مصر د هغه د کار او زیار په بدل کې ورکړم، ځکه چې عسکرو یې زما دپاره کار کړی دی. ما څښتن تعالی داسې ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_20.mp3', '', 1761754199, 1761754199),
(42424, 'Ezekiel 29:21', 'Ezekiel', 29, 21, 'کله چې داسې وشي، نو زه به د اسراییلو قوم یوځل بیا قوي کړم. ای حزقیاله، زه به تا پرېږدم چې خبرې وکړې او ستا خبرې به ټول واوري، نو بیا به هغوی په دې پوه شي چې زه څښتن یم.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/ezekiel29_verse_21.mp3', '', 1761754199, 1761754199),
(42425, 'Genesis 45:1', 'Genesis', 45, 1, 'یوسف نور د خپلو نوکرانو په مخکې ځان ټینګ نه کړای شو. هغه چیغې کړې: «ټول د کوټې څخه ووځئ!» نو کله چې یوسف خپل ځان خپلو ورونو ته وروپېژانده هلته بل څوک نه ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_1.mp3', '', 1761754199, 1761754199),
(42426, 'Genesis 45:2', 'Genesis', 45, 2, 'هغه په داسې لوړ اواز سره وژړل چې مصریانو دا ژړا واورېدله او د فرعون درباریانو هم دا خبره واورېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_2.mp3', '', 1761754199, 1761754199),
(42427, 'Genesis 45:3', 'Genesis', 45, 3, 'یوسف خپلو ورونو ته وویل: «زه یوسف یم! ایا زما پلار لا تر‌اوسه پورې ژوندی دی؟» خو کله چې د هغه ورونو دا خبره واورېدله، ډېر سخت ووېرېدل. ورونو یې نه شو کولای چې هغه ته ځواب ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_3.mp3', '', 1761754199, 1761754199),
(42428, 'Genesis 45:4', 'Genesis', 45, 4, 'بیا یوسف خپلو ورونو ته وویل: «ماته رانژدې شئ.» کله چې هغوی ورنژدې شول، هغه وویل: «زه ستاسو ورور یوسف یم، هغه یوسف چې تاسو د نورو په لاس په مصر کې خرڅ کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_4.mp3', '', 1761754199, 1761754199),
(42429, 'Genesis 45:5', 'Genesis', 45, 5, 'اوس مه پرېشانه کېږئ او خپل ځانونه په دې باندې مه ملامتوئ چې زه تاسو دلته خرڅ کړم، ځکه چې خدای زه ستاسو څخه مخکې د خلکو د ژوند د ژغورلو دپاره دلته رالېږلی یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_5.mp3', '', 1761754199, 1761754199),
(42430, 'Genesis 45:6', 'Genesis', 45, 6, 'ځکه چې دوه کاله کیږي چې په دې هېواد کې قحطي ده او د راتلونکو پنځو کالو دپاره به دلته کرل او رېبل نه وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_6.mp3', '', 1761754199, 1761754199),
(42431, 'Genesis 45:7', 'Genesis', 45, 7, 'خو خدای زه ستاسو څخه مخکې راولېږلم چې تاسو په یوه عجیبه طریقه وژغوري چې تاسې او ستاسو اولاده ژوندي پاتې شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_7.mp3', '', 1761754199, 1761754199),
(42432, 'Genesis 45:8', 'Genesis', 45, 8, 'نو په رښتیا سره تاسو زه دلته نه یم رالېږلی، بلکې خدای رالېږلی یم. هغه زه د فرعون ډېر لوړ‌رتبه درباري وټاکلم او زه د ټول هېواد دوهم واکمن یم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_8.mp3', '', 1761754199, 1761754199),
(42433, 'Genesis 45:9', 'Genesis', 45, 9, 'اوس زر شئ، زما پلار ته بېرته ورشئ او هغه ته ووایئ چې ستا زوی یوسف داسې وایي چې خدای زه د مصر دوهم مشر کړی یم. بې له کومه ځنډه ماته راشئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_9.mp3', '', 1761754199, 1761754199),
(42434, 'Genesis 45:10', 'Genesis', 45, 10, 'تاسو به د جوشن په سیمه کې اوسېږئ، ترڅو تاسو، ستاسو اولادونه، ستاسو لمسیان، ستاسو رمې او پادې او خپلو ټولو شیانو سره چې درسره دي زما سره نژدې اوسئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_10.mp3', '', 1761754199, 1761754199),
(42435, 'Genesis 45:11', 'Genesis', 45, 11, 'زه به هلته په تاسو پام کوم، ځکه چې د قحطۍ پنځه کاله لا پاتې دي. که تاسو رانه شئ نو تاسو، ستاسو کورنۍ او ستاسو حیوانات به له لوږې څخه مړه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_11.mp3', '', 1761754199, 1761754199),
(42436, 'Genesis 45:12', 'Genesis', 45, 12, 'تاسو په خپله او همدارنګه زما ورور بنیامین ویني چې په رښتیا سره دا زه یم چې تاسو سره خبرې کوم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_12.mp3', '', 1761754199, 1761754199),
(42437, 'Genesis 45:13', 'Genesis', 45, 13, 'نو زما پلار په مصر کې زما د عزت او هغه څه څخه چې تاسو ولیدل، خبر کړئ او زر هغه دلته راولئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_13.mp3', '', 1761754199, 1761754199),
(42438, 'Genesis 45:14', 'Genesis', 45, 14, 'بیا هغه خپل لاسونه د خپل ورور بنیامین څخه راتاو کړل او ویې ژړل او بنیامین هغه په غېږ کې ونیوه او ویې ژړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_14.mp3', '', 1761754199, 1761754199),
(42439, 'Genesis 45:15', 'Genesis', 45, 15, 'هغه خپل ټول ورونه ښکل کړل او ورته ویې ژړل. له هغې نه وروسته ورونو یې ورسره خبرې وکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_15.mp3', '', 1761754199, 1761754199),
(42440, 'Genesis 45:16', 'Genesis', 45, 16, 'کله چې د فرعون ماڼۍ ته د یوسف د ورونو د راتللو خبر ورسېده، نو فرعون او د هغه ټول درباریان خوشحاله شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_16.mp3', '', 1761754199, 1761754199),
(42441, 'Genesis 45:17', 'Genesis', 45, 17, 'فرعون یوسف ته وویل: «خپلو ورونو ته ووایه چې داسې وکړئ، خپل حیوانات بار کړئ او د کنعان خاورې ته ستانه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_17.mp3', '', 1761754199, 1761754199),
(42442, 'Genesis 45:18', 'Genesis', 45, 18, 'خپل پلار او خپلې کورنۍ ماته راولئ. هغوی ته به د مصر تر ټولو ښه ځمکه ورکړم او هغوی به د خپل ژوندانه د اړتیا څخه زیات ولري.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_18.mp3', '', 1761754199, 1761754199),
(42443, 'Genesis 45:19', 'Genesis', 45, 19, 'تاته زما امر دی چې هغوی ته ووایه: ‹داسې وکړئ چې د مصر څخه د خپلو اولادونو او خپلو ښځو دپاره ګاډۍ‌ګانې بوځئ او خپل پلار د ځان سره راواخلئ او راشئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_19.mp3', '', 1761754199, 1761754199),
(42444, 'Genesis 45:20', 'Genesis', 45, 20, 'د هغو شیانو په اړه چې تاسو یې د ځان سره نه شئ راوړلی هېڅ اندېښنه مه کوئ، ځکه چې د مصر تر ټولو ښه ځمکه به ستاسو وي.›»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_20.mp3', '', 1761754199, 1761754199),
(42445, 'Genesis 45:21', 'Genesis', 45, 21, 'نو د یعقوب زامنو همداسې وکړل او لکه څنګه چې فرعون امر کړی ؤ، یوسف هغوی ته ګاډۍ‌ګانې ورکړې او هغوی ته یې د سفر خواړه هم ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_21.mp3', '', 1761754199, 1761754199),
(42446, 'Genesis 45:22', 'Genesis', 45, 22, 'هغوی هر یو ته یې یوه یوه جوړه کالي ورکړل، خو بنیامین ته یې درې سوه د سپینو زرو سکې او پنځه جوړه کالي ورکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_22.mp3', '', 1761754199, 1761754199),
(42447, 'Genesis 45:23', 'Genesis', 45, 23, 'او خپل پلار ته یې د مصر تر ټولو ښو شیانو څخه د خرو لس باره او په ډوډۍ، غلو دانو او نورو خوړو باندې بار لس خرې د هغه د سفر دپاره ولېږلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_23.mp3', '', 1761754199, 1761754199),
(42448, 'Genesis 45:24', 'Genesis', 45, 24, 'بیا هغه خپل ورونه رخصت کړل او څنګه چې روان شول، نو هغوی ته یې وویل: «په لاره کې شخړه مه کوئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_24.mp3', '', 1761754199, 1761754199),
(42449, 'Genesis 45:25', 'Genesis', 45, 25, 'نو دوی د مصر څخه ووتل او په کنعان کې خپل پلار یعقوب ته راغلل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_25.mp3', '', 1761754199, 1761754199),
(42450, 'Genesis 45:26', 'Genesis', 45, 26, 'هغه یې خبر کړ: «یوسف تر‌اوسه پورې ژوندی دی او د مصر دوهم واکمن دی.» یعقوب هک حیران شو او د هغوی په خبره یې باور ونه کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_26.mp3', '', 1761754199, 1761754199),
(42451, 'Genesis 45:27', 'Genesis', 45, 27, 'خو کله چې هغوی د یوسف ټولې خبرې یعقوب ته بیان کړې او هغه ګاډۍ‌ګانې یې چې یوسف د هغه د راوستلو دپاره رالېږلې وې ولیدلې، نو د هغوی په پلار یعقوب کې بېرته ساه راپیدا شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_27.mp3', '', 1761754199, 1761754199),
(42452, 'Genesis 45:28', 'Genesis', 45, 28, 'یعقوب وویل: «زه اوس کولی شم باور وکړم چې زما زوی یوسف تر‌اوسه پورې ژوندی دی. زه به لاړ شم او د خپل مرګ څخه مخکې به هغه ووینم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis45_verse_28.mp3', '', 1761754199, 1761754199),
(42453, 'Isaiah 47:1', 'Isaiah', 47, 1, 'څښتن وایي: «ای د پېغلې انجلۍ په شان بابله شه راښکته له خپل تخته او کښېنه د ځمکې خاورو باندې ځکه ته نه یې نور هغه ښکلې او نازکه پېغله!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_1.mp3', '', 1761754199, 1761754199),
(42454, 'Isaiah 47:2', 'Isaiah', 47, 2, 'اوس راواخله پل د ژرندې او اوړه کړه غنم لېرې کړه خپل نقاب! ښکلي کالي وباسه! لمن دې پورته کړه او له ویالو تېره شه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_2.mp3', '', 1761754199, 1761754199),
(42455, 'Isaiah 47:3', 'Isaiah', 47, 3, 'خلک به وویني چې ته یې لوڅه هغوی به وویني چې ته یې سپکه او شرمېدلې یې ته زه به واخلمه بدل له تا نه او وبه نه کړمه زه رحم په چا»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_3.mp3', '', 1761754199, 1761754199),
(42456, 'Isaiah 47:4', 'Isaiah', 47, 4, 'زمونږ ژغورونکی دی سپېڅلی خدای د اسراییلو د هغه نوم دی مطلق قادر څښتن', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_4.mp3', '', 1761754199, 1761754199),
(42457, 'Isaiah 47:5', 'Isaiah', 47, 5, 'څښتن بابل ته وایي: «تیارې ته لاړه شه او کښېنه غلې ځکه چې تاته به نور څوک د پاچاهیو ملکه نه وایي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_5.mp3', '', 1761754199, 1761754199),
(42458, 'Isaiah 47:6', 'Isaiah', 47, 6, 'زه وم په قهر په خپل قوم باندې د هغوی سره مې داسې چلند وکړ چې ګوندې نور هغوی زما نه دي نو په دې خاطر مې په لاس درکړل تاته هغوی خو تا ونه کړلو رحم په هغوی باندې حتی تا کېښود ډېر دروند پېټی د سپین ږیرو په اوږو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_6.mp3', '', 1761754199, 1761754199),
(42459, 'Isaiah 47:7', 'Isaiah', 47, 7, 'تا ویل: ‹زه به تل یم ملکه› او ودې نه نیول نظر کې دا شیان او هېڅ وخت دې فکر نه ؤ کړی د دې کار پای ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_7.mp3', '', 1761754199, 1761754199),
(42460, 'Isaiah 47:8', 'Isaiah', 47, 8, 'نو دې خبرې ته اوس غوږ ونیسه ای د عیاشۍ سره مینه لرونکې فکر کوې چې ته یې په امن او په امان کې کوې دعوه چې بل څوک نشته زما په شان فکر کولو تا چې هېڅکله به کونډه نه شم یا به ونه وینم دا غم چې اولادونه مې له لاسه ورکړم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_8.mp3', '', 1761754199, 1761754199),
(42461, 'Isaiah 47:9', 'Isaiah', 47, 9, 'خو په یوه شېبه او یوه ورځ کې په ټول قدرت به په تا راشي دغه دواړه بلاګانې او سره له ټولو کوډو او جادو چې ترې کار اخلې خپل اولادونه او مېړه به ته له لاسه ورکړې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_9.mp3', '', 1761754199, 1761754199),
(42462, 'Isaiah 47:10', 'Isaiah', 47, 10, 'تا په امن کې ګڼلو خپل ځان په بدو کړنو سره تا کاوه فکر چې ما نه ویني هېڅوک بې لارې کړې یې ته خپل حکمت او پوهې او د خپل ځان سره دې دا وویل چې بل څوک نشته دی زما په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_10.mp3', '', 1761754199, 1761754199),
(42463, 'Isaiah 47:11', 'Isaiah', 47, 11, 'خو په تا باندې به راشي مصیبت او مخنیوی به یې ونه شي کړای کوډې او جادو هم ستا په تا به راشي مصیبت او خلاصولی به ترې نه شي خپل ځان په تا به راشي تباهي ناڅاپه یوه داسې تباهي چې دې په خوب کې هم لیدلې نه وي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_11.mp3', '', 1761754199, 1761754199),
(42464, 'Isaiah 47:12', 'Isaiah', 47, 12, 'تا د ځوانۍ له وخته زیار وېسته چې ډېرو کوډو څخه کار واخلې نو هغو کوډو ته دوام ورکړه شي کېدای چې بریالۍ شې او ووېروې خپل دښمنان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_12.mp3', '', 1761754199, 1761754199),
(42465, 'Isaiah 47:13', 'Isaiah', 47, 13, 'چې درکول کیږي تاته کومې مشورې ته له هغو نه ستړې شوې یې چېرې دي هغه نجومیان ستا چې ګوري ستورو ته او کړي د هغو څېړنه او پېشګویي کړي میاشت په میاشت چې په تا څه پېښیږي هغوی دې راشي او تا دې وژغوري', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_13.mp3', '', 1761754199, 1761754199),
(42466, 'Isaiah 47:14', 'Isaiah', 47, 14, 'خو پوه شه چې نجومیان به وسوځي اور کې لکه د بوسو په شان وبه نه لري د دې وس او توان چې ځان وژغوري د اور له سرو لمبو نه دا به نه وي د سکرو د اور په شان چې انسان کښېني او ورته تود کړي خپل ځان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_14.mp3', '', 1761754199, 1761754199),
(42467, 'Isaiah 47:15', 'Isaiah', 47, 15, 'دي همدا نجومیان چې تا زیار اېستلی چې مشوره ترې واخلې او له ځوانۍ نه دې دا کار کاوه هغوی به پرېږدي تا او په خپله لاره به ځي او پاتې به نه شي څوک چې تا وژغوري»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah47_verse_15.mp3', '', 1761754199, 1761754199),
(42468, 'Job 22:1', 'Job', 22, 1, 'بيا تيمانى اليفز جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_1.mp3', '', 1761754199, 1761754199),
(42469, 'Job 22:2', 'Job', 22, 2, '”بنى آدم خُدائ پاک له څۀ فائده ورکولے شى؟ د ټولو نه هوښيار کس هم د هغۀ مدد کولے شى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_2.mp3', '', 1761754199, 1761754199),
(42470, 'Job 22:3', 'Job', 22, 3, 'د قادر خُدائ دپاره به څۀ خوشحالى وى کۀ تۀ صادق شې، کۀ ته خپل عملونه صفا کړې نو هغۀ له به څۀ فائده ورکړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_3.mp3', '', 1761754199, 1761754199),
(42471, 'Job 22:4', 'Job', 22, 4, 'چې تۀ پرهيزګار يې نو ځکه هغه په تا اِلزام لګوى او ولې ستا خِلاف د عدالت نه کار اخلى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_4.mp3', '', 1761754199, 1761754199),
(42472, 'Job 22:5', 'Job', 22, 5, 'نه، هغه وجه ده چې ستا بدعملى زياته ده او ستا د ګناهونو ختمېدل نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_5.mp3', '', 1761754199, 1761754199),
(42473, 'Job 22:6', 'Job', 22, 6, 'لکه چې تا د خپلو وروڼو نه د قرض پېسې په زور اخستې دى، او تا د هغوئ نه جامې ويستې دى او بربنډ دې پرېښى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_6.mp3', '', 1761754199, 1761754199),
(42474, 'Job 22:7', 'Job', 22, 7, 'تا تږو کسانو له اوبۀ نۀ دى ورکړې، او تا د نهَرو کسانو نه روټۍ ايساره کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_7.mp3', '', 1761754199, 1761754199),
(42475, 'Job 22:8', 'Job', 22, 8, 'تا د خپل طاقت او حيثيت نه کار واخستلو او په ټول مُلک دې قبضه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_8.mp3', '', 1761754199, 1761754199),
(42476, 'Job 22:9', 'Job', 22, 9, 'تا کونډې تش لاس لېږلې دى، او يتيمان دې نااُميده کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_9.mp3', '', 1761754199, 1761754199),
(42477, 'Job 22:10', 'Job', 22, 10, 'نو په دې وجه ستا نه ګېرچاپېره دامونه دى، او يوه ناڅاپه يره به په تا باندې غالبه شى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_10.mp3', '', 1761754199, 1761754199),
(42478, 'Job 22:11', 'Job', 22, 11, 'يا يوه داسې تيارۀ چې تۀ نور هيڅ نۀ شې ليدلے، د اوبو يو سېلاب به تا پټ کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_11.mp3', '', 1761754199, 1761754199),
(42479, 'Job 22:12', 'Job', 22, 12, 'پاس په آسمانونو کښې خُدائ پاک نشته څۀ؟ پاس ستورى وګوره چې څومره اوچت دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_12.mp3', '', 1761754199, 1761754199),
(42480, 'Job 22:13', 'Job', 22, 13, 'نو دا ځکه تۀ وائې چې تۀ څۀ کوې نو خُدائ پاک ته پته نۀ لګى، هغه په توره وريځ کښې پټ دے نو هغه څنګه عدالت کولے شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_13.mp3', '', 1761754199, 1761754199),
(42481, 'Job 22:14', 'Job', 22, 14, 'تکه توره وريځ د هغۀ نه تاو شى نو هغه کتل نۀ شى کولے، او هغه په عرش باندې مزل کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_14.mp3', '', 1761754199, 1761754199),
(42482, 'Job 22:15', 'Job', 22, 15, 'تۀ به په هغه زړو لارو ځې څۀ، چې په کومو باندې بدعمله کسان تلل؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_15.mp3', '', 1761754199, 1761754199),
(42483, 'Job 22:16', 'Job', 22, 16, 'د هغوئ دوران راتلو نه مخکښې سېلاب هغوئ لاهو کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_16.mp3', '', 1761754199, 1761754199),
(42484, 'Job 22:17', 'Job', 22, 17, 'هغوئ خُدائ پاک ته وئيلى وُو چې زمونږ نه قلار شه، او داسې يقين يې لرلو چې قادر خُدائ د هغوئ هيڅ هم نۀ شى کولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_17.mp3', '', 1761754199, 1761754199),
(42485, 'Job 22:18', 'Job', 22, 18, 'خو بيا هم هغه خُدائ پاک وو چې دوئ يې مالداره کړل، نو ځکه زۀ د بدعمله خلقو په خيالونو هيڅ غرض نۀ ساتم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_18.mp3', '', 1761754199, 1761754199),
(42486, 'Job 22:19', 'Job', 22, 19, 'صادقان د بدعمله تباهى ګورى او خوشحاليږى، خو بې‌ګناه کسان دوئ پورې خندا کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_19.mp3', '', 1761754199, 1761754199),
(42487, 'Job 22:20', 'Job', 22, 20, 'وائى چې زمونږ دشمنان څنګه تباه شوى دى، او چې د هغوئ څۀ پاتې وُو هغه اور تباه کړى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_20.mp3', '', 1761754199, 1761754199),
(42488, 'Job 22:21', 'Job', 22, 21, 'خُدائ پاک ته خپل ځان حواله کړئ، او د هغۀ سره روغه وکړئ، او ستاسو هر کار به سم وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_21.mp3', '', 1761754199, 1761754199),
(42489, 'Job 22:22', 'Job', 22, 22, 'د هغۀ په تعليماتو عمل کوئ، او د هغۀ خبرې زړۀ ته کوزې کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_22.mp3', '', 1761754199, 1761754199),
(42490, 'Job 22:23', 'Job', 22, 23, 'کۀ تاسو قادر خُدائ ته راواپس شئ، نو تاسو به په خپل ځائ باندې بيا ولګئ، کۀ تاسو د خپل ژوند نه بدى وباسئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_23.mp3', '', 1761754199, 1761754199),
(42491, 'Job 22:24', 'Job', 22, 24, 'کۀ تاسو سرۀ زر خاورې وګڼئ، او د اوفير سوچه سرۀ زر د سيند د کاڼو په شان وګڼئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_24.mp3', '', 1761754199, 1761754199),
(42492, 'Job 22:25', 'Job', 22, 25, 'نو بيا قادر خُدائ په خپله ستاسو د سرو زرو په شان دے او هغه ستاسو قيمتى سپين زر دے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_25.mp3', '', 1761754199, 1761754199),
(42493, 'Job 22:26', 'Job', 22, 26, 'نو بيا به تاسو د قادر خُدائ سره خوشحاله اوسئ، او د زړۀ نه به هغۀ سره ملاقات کولے شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_26.mp3', '', 1761754199, 1761754199),
(42494, 'Job 22:27', 'Job', 22, 27, 'نو تاسو به هغۀ ته سوال وکړئ او هغه به ستاسو سوال قبول کړى، او تاسو به خپل قسمونه پوره کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_27.mp3', '', 1761754199, 1761754199),
(42495, 'Job 22:28', 'Job', 22, 28, 'تاسو به په هر کار کښې کامياب يئ، او ستاسو لار به روښانه وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_28.mp3', '', 1761754199, 1761754199),
(42496, 'Job 22:29', 'Job', 22, 29, 'کله چې خُدائ پاک خلق کمزورى کړى نو تۀ وائې دا ځکه چې هغوئ مغروره وُو، خو په اصل کښې خُدائ پاک خلق په دې طريقې سره بچ کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_29.mp3', '', 1761754199, 1761754199),
(42497, 'Job 22:30', 'Job', 22, 30, 'ځکه چې خُدائ پاک بې‌ګناه خلق بچ کوى، کۀ چرې تۀ بې‌ګناه يې نو هغه به تا هم بچ کړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job22_verse_30.mp3', '', 1761754199, 1761754199),
(42498, 'Job 15:1', 'Job', 15, 1, 'نو تيمانى اليفز جواب ورکړو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_1.mp3', '', 1761754199, 1761754199),
(42499, 'Job 15:2', 'Job', 15, 2, '”يو هوښيار کس دې تشې خبرې وکړى څۀ، او هغه دې هسې بې‌مطلبه خبرې وکړى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_2.mp3', '', 1761754199, 1761754199),
(42500, 'Job 15:3', 'Job', 15, 3, 'هغوئ دې په بې‌فائدې خبرو باندې بحث کوى څۀ، يا په داسې خبرو باندې چې د هغې هيڅ مقصد نۀ وى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_3.mp3', '', 1761754199, 1761754199),
(42501, 'Job 15:4', 'Job', 15, 4, 'خو تۀ د خُدائ پاک نه هيڅ يره نۀ لرې، او د خُدائ پاک د عبادت لاره نيسې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_4.mp3', '', 1761754199, 1761754199),
(42502, 'Job 15:5', 'Job', 15, 5, 'ځکه چې ستا ګناه ستا ژبې ته ښودنه کوى، او تا د دوکه باز ژبه خوښه کړې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_5.mp3', '', 1761754199, 1761754199),
(42503, 'Job 15:6', 'Job', 15, 6, 'دا زۀ نۀ يم، خپله ژبه تا ته بد وائى، ستا خپله خولۀ ستا خِلاف ګواهى ورکوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_6.mp3', '', 1761754199, 1761754199),
(42504, 'Job 15:7', 'Job', 15, 7, 'تۀ د بنى آدم د نسل وړومبے پېدا شوے کس يې څۀ؟ تۀ د غرونو نه مخکښې پېدا شوے يې څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_7.mp3', '', 1761754199, 1761754199),
(42505, 'Job 15:8', 'Job', 15, 8, 'تا د خُدائ پاک د راز منصوبې واورېدې څۀ؟ او ستا څۀ خيال دے ولې تۀ يواځې هوښيار يې څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_8.mp3', '', 1761754199, 1761754199),
(42506, 'Job 15:9', 'Job', 15, 9, 'تا سره داسې څۀ عِلم دے چې مونږ سره نشته؟ تۀ داسې په څۀ پوهېږې چې مونږ پرې نۀ پوهيږو؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_9.mp3', '', 1761754199, 1761754199),
(42507, 'Job 15:10', 'Job', 15, 10, 'سپين‌ږيرى او بوډاګان زمونږ په طرف باندې دى، کوم چې ستا د پلار نه ډېر مشران دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_10.mp3', '', 1761754199, 1761754199),
(42508, 'Job 15:11', 'Job', 15, 11, 'د خُدائ پاک تسلى ستا دپاره کمه ده څۀ؟ د هغۀ نرمې خبرې ستا دپاره کافى نۀ دى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_11.mp3', '', 1761754199, 1761754199),
(42509, 'Job 15:12', 'Job', 15, 12, 'تۀ د خپلو جذباتو نه کار ولې اخلې؟ او ستا رنګ ولې دومره سور دے', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_12.mp3', '', 1761754199, 1761754199),
(42510, 'Job 15:13', 'Job', 15, 13, 'چې خُدائ پاک ته غصه يې؟ او ستا د خولې نه داسې ګډې وډې خبرې وځى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_13.mp3', '', 1761754199, 1761754199);